  "noticeReopen": "儲存空間說明",
  "noticeLabel": "瀏覽器儲存空間說明",
  "noticeText": "Cook 使用瀏覽器儲存空間來支援你所使用的烹飪和登入功能。不會新增任何廣告或分析用的儲存空間。",
  "noticeClose": "關閉儲存空間說明",
  "privDraftLabel": "草案 — 更新於 2026 年 10 月 28 日。",
  "privDraft": "帳戶功能目前正在測試中。以下營運者和服務資訊必須在公開上線前補齊。",
  "privWho1": "Cook 由［營運者的法定名稱和郵寄地址］營運。如有隱私權問題或請求，請聯絡［隱私權電子郵件地址］。這些資訊必須在開放註冊前補齊。",
  "privWhat1": "當你建立帳戶時，我們會使用你的電子郵件、帳戶識別碼、密碼驗證紀錄和驗證狀態來提供並保護你的帳戶。密碼由驗證服務供應商以安全雜湊形式處理；Cook 不會儲存可讀取的密碼。我們會儲存你的廚房配置、所選語言、主題和計量單位，以便在所有裝置上還原你的設定。建立帳戶需要電子郵件和密碼；不登入也能瀏覽食譜。",
  "privWhat2": "處理帳戶和設定資料是提供你所要求之帳戶服務所必需（GDPR 第 6 條第 1 項 (b) 款）。為維護安全和防止濫用，有限的紀錄可能會基於正當利益（第 6 條第 1 項 (f) 款）處理，以必要為限並經過權衡。驗證信和密碼重設信屬於服務訊息，而非行銷。帳戶功能不會新增任何廣告或分析。",
  "privStorage1": "Cook 使用 sessionStorage 在同一分頁的不同頁面之間保留你的廚房、烹飪進度和選擇。登入後，它也會保存你的驗證工作階段。瀏覽器通常會在分頁工作階段結束時清除這些資料，但瀏覽器的工作階段還原功能可能會保留它們。登出會清除 Cook 的分頁資料。關閉儲存空間說明的狀態只會在該分頁中記住。Cook 自己的指令碼不會設定 Cookie。你的主機或服務供應商可能有自己的安全處理，必須在上線前記錄在案。",
  "privStorage2": "儲存空間說明中的「確定」和關閉按鈕只會關閉說明。它們不代表同意分析、廣告或其他選用追蹤。日後任何非必要的儲存都需要在開始前另行選擇，而且拒絕和撤回同樣簡單。",
  "privOther1": "目前食譜清單的語音功能會根據你的 IP 位址向 country.is 查詢大致所在國家，以選擇語音辨識語言。如果你使用麥克風辨識，瀏覽器可能會將音訊傳送給其語音辨識服務供應商。你也可以手動輸入食材。在公開上線前，必須審查這些供應商、它們的政策以及這些功能的法律依據。",
  "privProviders1": "預計使用的帳戶服務供應商：Supabase（代管 PostgreSQL 和驗證），使用所選的歐盟資料庫區域。電子郵件服務供應商：［供應商］。網站主機：［供應商］。營運者必須確認實際的供應商、資料處理協議、次處理者、日誌存放位置，以及向歐洲經濟區以外的任何傳輸。歐盟資料庫區域本身並不能排除跨境傳輸。如適用，請註明適用的適足性認定或契約保障措施，以及如何取得其副本。",
  "privRetention1": "帳戶設定會在你的帳戶有效期間保留。你可以透過上方的隱私權聯絡方式要求刪除。上線前，營運者必須明訂刪除請求的處理流程、未驗證帳戶的到期時間，以及安全日誌和備份的保存期限。已刪除的資料可能會保留在存取受限的備份中，直到記錄在案的備份保存期限結束。",
  "privRights1": "依適用條件，你可以要求存取、更正、刪除、限制處理或資料可攜，或反對基於正當利益的處理。請聯絡上方的營運者；請求通常會在一個月內獲得回覆，如依法延長會說明原因。你可以向監管機關申訴，包括匈牙利的 NAIH（naih.hu）。Cook 不會將帳戶設定用於產生法律效果或類似重大影響的自動化決策。",
