  "Rough paste": "粗泥",
  "Mix the oyster sauce, both soy sauces, fish sauce, sugar and water.": "蠔油、兩種醬油、魚露、糖和水調勻。",
  "Heat the oil in the wok until very hot and fry the eggs one at a time, spooning hot oil over them, until the edges are crispy and the yolk is still runny. Keep them on a plate.": "炒鍋裡把油燒得很熱，雞蛋一個一個煎，邊煎邊舀熱油澆在上面，煎到邊緣焦脆、蛋黃仍是流心。盛到盤裡備用。",
  "Crispy edges, runny yolk": "邊緣焦脆，蛋黃流心",
  "Fry the garlic and chilies": "爆香蒜和辣椒",
  "Heat the oil in the wok and fry the garlic and chili paste for a few seconds until fragrant.": "炒鍋熱油，把蒜辣椒泥炒幾秒鐘直到出香味。",
  "Fragrant, not brown": "出香味，沒有變色",
